<script setup lang="ts">import{ref}from'vue';import{useRouter}from'vue-router';import{useAuthStore}from'../../stores/auth';import PageHeader from'../../components/PageHeader.vue';const confirm=ref(false);const auth=useAuthStore();const router=useRouter();const items=['账号与安全','设备管理','消息设置','隐私设置','举报反馈','账号合并','加入我们','网站客服'];function logout(){auth.logout();void router.push('/login');}</script><template><main class="page business-page"><PageHeader title="系统设置"/><section class="menu-group settings-menu"><button v-for="item in items" :key="item"><b>{{item}}</b><span>›</span></button></section><button class="logout-button" aria-label="退出登录" @click="confirm=true">退出登录</button><div v-if="confirm" class="dialog-backdrop" @click.self="confirm=false"><section class="pay-dialog" role="dialog"><h2>退出登录</h2><p>确认退出当前账号？</p><div><button class="ghost-button" @click="confirm=false">取消</button><button class="primary-button" @click="logout">确认退出</button></div></section></div></main></template>
